<script>
/* =====================================================================
   NEON LINE — Cyberpunk Monorail / Rain / Holographic Metropolis
   Single-file Three.js r128 build.
   ===================================================================== */
(function () {
    "use strict";

    // ---------- Renderer ----------
    const canvas = document.getElementById("scene");
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: "high-performance" });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x02030a, 1);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;

    // ---------- Scene & Fog ----------
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x02030a, 0.0125);

    // ---------- Camera ----------
    const camera = new THREE.PerspectiveCamera(62, window.innerWidth / window.innerHeight, 0.1, 600);
    camera.position.set(14, 9, 22);

    const controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 4.5, -12);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.35;
    controls.minDistance = 4;
    controls.maxDistance = 120;
    controls.maxPolarAngle = Math.PI * 0.52;

    // ---------- Palette ----------
    const C = {
        cyan:    0x2af6ff,
        magenta: 0xff2bd6,
        purple:  0x9b3cff,
        amber:   0xffb347,
        blue:    0x2d7bff,
        green:   0x27ffa8,
        pink:    0xff2f6b,
        dark:    0x05070f
    };

    // ---------- Lighting ----------
    scene.add(new THREE.AmbientLight(0x101826, 0.9));

    const hemi = new THREE.HemisphereLight(0x14304a, 0x22061a, 0.55);
    scene.add(hemi);

    const key = new THREE.DirectionalLight(0xff2bd6, 0.7);
    key.position.set(-30, 40, 10);
    scene.add(key);

    const fill = new THREE.DirectionalLight(0x2af6ff, 0.45);
    fill.position.set(30, 25, -20);
    scene.add(fill);

    // Track-side neon pools
    const trackLights = [];
    for (let i = 0; i < 6; i++) {
        const pl = new THREE.PointLight(i % 2 ? C.cyan : C.magenta, 1.4, 40, 2);
        scene.add(pl);
        trackLights.push(pl);
    }

    // =====================================================================
    //  TEXTURE FACTORIES (canvas-generated)
    // =====================================================================
    function makeWindowTexture(cols, rows, baseHex) {
        const w = 64, h = 128;
        const cv = document.createElement("canvas");
        cv.width = w; cv.height = h;
        const g = cv.getContext("2d");
        g.fillStyle = "#04060c"; g.fillRect(0, 0, w, h);
        const pal = ["#2af6ff", "#ff2bd6", "#ffb347", "#9b3cff", "#27ffa8", "#ffffff"];
        const cw = w / cols, ch = h / rows;
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                if (Math.random() < 0.55) {
                    const col = pal[(Math.random() * pal.length) | 0];
                    g.fillStyle = col;
                    g.globalAlpha = 0.45 + Math.random() * 0.55;
                    g.fillRect(x * cw + 1, y * ch + 1, cw - 2, ch - 2);
                    g.globalAlpha = 1;
                }
            }
        }
        // faint horizontal structural bands
        g.strokeStyle = baseHex; g.globalAlpha = 0.18; g.lineWidth = 1;
        for (let y = 0; y <= rows; y++) { g.beginPath(); g.moveTo(0, y * ch); g.lineTo(w, y * ch); g.stroke(); }
        const tex = new THREE.CanvasTexture(cv);
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.magFilter = THREE.NearestFilter;
        return tex;
    }

    function makeBillboardTexture(kind) {
        const w = 256, h = 160;
        const cv = document.createElement("canvas");
        cv.width = w; cv.height = h;
        const g = cv.getContext("2d");
        g.clearRect(0, 0, w, h);
        const pal = ["#ff2bd6", "#2af6ff", "#ffb347", "#9b3cff", "#27ffa8"];
        const main = pal[(Math.random() * pal.length) | 0];
        // holographic blocks
        for (let i = 0; i < 8; i++) {
            g.fillStyle = Math.random() < 0.7 ? main : pal[(Math.random() * pal.length) | 0];
            g.globalAlpha = 0.35 + Math.random() * 0.5;
            const bw = 30 + Math.random() * 120, bh = 10 + Math.random() * 26;
            g.fillRect(Math.random() * (w - bw), Math.random() * (h - bh), bw, bh);
        }
        g.globalAlpha = 1;
        g.strokeStyle = main; g.lineWidth = 2; g.strokeRect(4, 4, w - 8, h - 8);
        g.fillStyle = main; g.font = "bold 26px monospace"; g.fillText(kind, 14, 34);
        g.fillStyle = "#ffffff"; g.font = "12px monospace"; g.globalAlpha = 0.7;
        g.fillText("0x" + ((Math.random() * 0xffff) | 0).toString(16).padStart(4, "0") + " //NET", 14, h - 14);
        const tex = new THREE.CanvasTexture(cv);
        return tex;
    }

    function makeGridTexture() {
        const s = 512;
        const cv = document.createElement("canvas"); cv.width = cv.height = s;
        const g = cv.getContext("2d");
        g.fillStyle = "#000"; g.fillRect(0, 0, s, s);
        g.strokeStyle = "rgba(42,246,255,0.5)"; g.lineWidth = 1;
        const step = 32;
        for (let i = 0; i <= s; i += step) {
            g.beginPath(); g.moveTo(i, 0); g.lineTo(i, s); g.stroke();
            g.beginPath(); g.moveTo(0, i); g.lineTo(s, i); g.stroke();
        }
        const tex = new THREE.CanvasTexture(cv);
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(40, 40);
        return tex;
    }

    function makeGlowSprite(hex) {
        const s = 128;
        const cv = document.createElement("canvas"); cv.width = cv.height = s;
        const g = cv.getContext("2d");
        const grd = g.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
        const col = new THREE.Color(hex);
        const rgb = col.getStyle();
        grd.addColorStop(0, "rgba(255,255,255,0.95)");
        grd.addColorStop(0.25, "rgba(" + col.r * 255 + "," + col.g * 255 + "," + col.b * 255 + ",0.7)");
        grd.addColorStop(1, "rgba(0,0,0,0)");
        g.fillStyle = grd; g.fillRect(0, 0, s, s);
        return new THREE.CanvasTexture(cv);
    }

    // Shared glow sprites
    const glowCyan    = makeGlowSprite(C.cyan);
    const glowMagenta = makeGlowSprite(C.magenta);
    const glowAmber   = makeGlowSprite(C.amber);
    const glowPurple  = makeGlowSprite(C.purple);
    const glowGreen   = makeGlowSprite(C.green);

    function additiveSprite(tex, size, opacity) {
        const m = new THREE.SpriteMaterial({ map: tex, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, opacity: opacity || 1 });
        const sp = new THREE.Sprite(m);
        sp.scale.set(size, size, 1);
        return sp;
    }

    // =====================================================================
    //  GROUND  (wet reflective floor + neon grid reflection)
    // =====================================================================
    const groundMat = new THREE.MeshStandardMaterial({
        color: 0x04060c, metalness: 0.92, roughness: 0.22, envMapIntensity: 0.4
    });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(600, 600), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = 0;
    scene.add(ground);

    const gridMat = new THREE.MeshBasicMaterial({
        map: makeGridTexture(), transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false
    });
    const gridPlane = new THREE.Mesh(new THREE.PlaneGeometry(600, 600), gridMat);
    gridPlane.rotation.x = -Math.PI / 2;
    gridPlane.position.y = 0.02;
    scene.add(gridPlane);

    // Faint reflective puddle streaks (emissive lines on floor)
    for (let i = 0; i < 24; i++) {
        const col = [C.cyan, C.magenta, C.purple, C.amber][(Math.random() * 4) | 0];
        const len = 20 + Math.random() * 60;
        const lm = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.10, blending: THREE.AdditiveBlending, depthWrite: false });
        const ln = new THREE.Mesh(new THREE.PlaneGeometry(0.5, len), lm);
        ln.rotation.x = -Math.PI / 2;
        ln.position.set((Math.random() - 0.5) * 120, 0.03, (Math.random() - 0.5) * 120);
        scene.add(ln);
    }

    // =====================================================================
    //  MONORAIL TRACK CURVE  (curving cyan rails like reference)
    // =====================================================================
    const trackPoints = [
        new THREE.Vector3(  60, 6.0,  40),
        new THREE.Vector3(  30, 6.2,  18),
        new THREE.Vector3(   8, 6.5,   4),
        new THREE.Vector3(  -6, 6.8, -10),
        new THREE.Vector3( -18, 7.2, -28),
        new THREE.Vector3( -34, 7.6, -52),
        new THREE.Vector3( -52, 8.0, -78)
    ];
    const curve = new THREE.CatmullRomCurve3(trackPoints, false, "catmullrom", 0.5);
    const curveLen = curve.getLength();

    // Central dark beam
    const beamMat = new THREE.MeshStandardMaterial({ color: 0x0a0e18, metalness: 0.85, roughness: 0.4 });
    const beam = new THREE.Mesh(new THREE.TubeGeometry(curve, 220, 0.55, 8, false), beamMat);
    scene.add(beam);

    // Two glowing rails offset horizontally
    function offsetCurve(offsetX) {
        const pts = [];
        for (let i = 0; i <= 220; i++) {
            const t = i / 220;
            const p = curve.getPointAt(t);
            const tan = curve.getTangentAt(t);
            const nrm = new THREE.Vector3(-tan.z, 0, tan.x).normalize();
            pts.push(p.clone().add(nrm.multiplyScalar(offsetX)));
        }
        return new THREE.CatmullRomCurve3(pts);
    }
    const railMat = new THREE.MeshBasicMaterial({ color: C.cyan, transparent: true, opacity: 0.95 });
    const railL = new THREE.Mesh(new THREE.TubeGeometry(offsetCurve(0.7), 220, 0.10, 6, false), railMat);
    const railR = new THREE.Mesh(new THREE.TubeGeometry(offsetCurve(-0.7), 220, 0.10, 6, false), railMat);
    scene.add(railL, railR);

    // Overhead catenary wire (for pantograph)
    function offsetCurveY(dy) {
        const pts = [];
        for (let i = 0; i <= 220; i++) { const t = i / 220; const p = curve.getPointAt(t); pts.push(p.clone().add(new THREE.Vector3(0, dy, 0))); }
        return new THREE.CatmullRomCurve3(pts);
    }
    const wireMat = new THREE.MeshBasicMaterial({ color: C.purple, transparent: true, opacity: 0.7 });
    const wire = new THREE.Mesh(new THREE.TubeGeometry(offsetCurveY(2.6), 220, 0.05, 4, false), wireMat);
    scene.add(wire);

    // Pylons supporting the beam
    for (let i = 0; i <= 12; i++) {
        const t = i / 12;
        const p = curve.getPointAt(t);
        const h = p.y;
        const col = i % 2 ? C.cyan : C.magenta;
        const pylonMat = new THREE.MeshStandardMaterial({ color: 0x0a0e18, metalness: 0.8, roughness: 0.5 });
        const pylon = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.3, h, 8), pylonMat);
        pylon.position.set(p.x, h / 2, p.z);
        scene.add(pylon);
        // glowing ring on pylon top
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.06, 6, 18), new THREE.MeshBasicMaterial({ color: col }));
        ring.rotation.x = Math.PI / 2; ring.position.set(p.x, p.y - 0.2, p.z);
        scene.add(ring);
        const gr = additiveSprite(col === C.cyan ? glowCyan : glowMagenta, 2.2, 0.6);
        gr.position.set(p.x, p.y - 0.2, p.z); scene.add(gr);
    }

    // Place track lights along curve
    for (let i = 0; i < trackLights.length; i++) {
        const p = curve.getPointAt((i + 0.5) / trackLights.length);
        trackLights[i].position.set(p.x, p.y - 1.0, p.z);
    }

    // =====================================================================
    //  THE MONORAIL TRAIN
    // =====================================================================
    const train = new THREE.Group();

    // Main body (rounded-ish)
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0x11151f, metalness: 0.9, roughness: 0.35 });
    const body = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.5, 10), bodyMat);
    body.position.y = 1.0;
    train.add(body);

    // Roof cap
    const roof = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.35, 9.6), new THREE.MeshStandardMaterial({ color: 0x1a2230, metalness: 0.9, roughness: 0.3 }));
    roof.position.y = 1.9; train.add(roof);

    // Nose cone (front)
    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.95, 2.4, 12), bodyMat);
    nose.rotation.x = -Math.PI / 2; nose.position.set(0, 1.0, 5.6); train.add(nose);

    // Cockpit glow window (front face)
    const cockpitMat = new THREE.MeshBasicMaterial({ color: C.magenta });
    const cockpit = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.7), cockpitMat);
    cockpit.position.set(0, 1.25, 4.7); train.add(cockpit);
    const cockpitGlow = additiveSprite(glowMagenta, 2.6, 0.85); cockpitGlow.position.set(0, 1.25, 5.0); train.add(cockpitGlow);

    // Side window strips (emissive)
    const winStripMat = new THREE.MeshBasicMaterial({ color: C.cyan });
    [-1, 1].forEach(s => {
        const strip = new THREE.Mesh(new THREE.PlaneGeometry(9.2, 0.55), winStripMat);
        strip.rotation.y = s === 1 ? Math.PI / 2 : -Math.PI / 2;
        strip.position.set(s * 0.86, 1.25, 0);
        train.add(strip);
    });
    // continuous side glow sprite strip
    const sideGlowL = additiveSprite(glowCyan, 4, 0.4); sideGlowL.position.set(1.1, 1.25, 0); sideGlowL.scale.set(10, 1.4, 1); train.add(sideGlowL);
    const sideGlowR = additiveSprite(glowCyan, 4, 0.4); sideGlowR.position.set(-1.1, 1.25, 0); sideGlowR.scale.set(10, 1.4, 1); train.add(sideGlowR);

    // Neon underline trim
    const trimMat = new THREE.MeshBasicMaterial({ color: C.amber });
    const trim = new THREE.Mesh(new THREE.BoxGeometry(1.85, 0.08, 10.1), trimMat);
    trim.position.y = 0.25; train.add(trim);
    const trimGlow = additiveSprite(glowAmber, 4, 0.5); trimGlow.scale.set(11, 0.8, 1); trimGlow.position.y = 0.25; train.add(trimGlow);

    // Fins / stabilizers
    [-1, 1].forEach(s => {
        const fin = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 2.2), new THREE.MeshStandardMaterial({ color: 0x22304a, metalness: 0.7, roughness: 0.5 }));
        fin.position.set(s * 1.0, 0.7, -3.4); fin.rotation.z = s * 0.25; train.add(fin);
    });

    // Pantograph arm to overhead wire
    const pantMat = new THREE.MeshBasicMaterial({ color: C.purple });
    const pantArm = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 2.6, 6), pantMat);
    pantArm.position.set(0, 3.3, -1.2); train.add(pantArm);
    const pantShoe = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.08, 0.3), pantMat);
    pantShoe.position.set(0, 4.6, -1.2); train.add(pantShoe);
    const spark = additiveSprite(glowPurple, 1.4, 0.9); spark.position.set(0, 4.6, -1.2); train.add(spark);

    // Engine thrusters (rear) + glow + light
    const thrusterMat = new THREE.MeshBasicMaterial({ color: C.amber });
    const thrusterLights = [];
    [-1, 1].forEach(s => {
        const cone = new THREE.Mesh(new THREE.ConeGeometry(0.45, 1.2, 10), thrusterMat);
        cone.rotation.x = Math.PI / 2; cone.position.set(s * 0.55, 0.85, -5.2); train.add(cone);
        const g = additiveSprite(glowAmber, 2.4, 0.9); g.position.set(s * 0.55, 0.85, -5.9); train.add(g);
        const pl = new THREE.PointLight(C.amber, 1.2, 12, 2); pl.position.set(s * 0.55, 0.85, -5.6); train.add(pl);
        thrusterLights.push({ light: pl, glow: g });
    });

    // Headlight beam
    const head = new THREE.SpotLight(C.cyan, 2.2, 40, 0.5, 0.6, 1.5);
    head.position.set(0, 1.2, 5.5);
    const headTarget = new THREE.Object3D(); headTarget.position.set(0, 0.5, 25); train.add(headTarget); head.target = headTarget;
    train.add(head);
    const headGlow = additiveSprite(glowCyan, 2.0, 0.9); headGlow.position.set(0, 1.2, 5.6); train.add(headGlow);

    // Undercarriage connector to beam
    const under = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 3), new THREE.MeshStandardMaterial({ color: 0x1a2230, metalness: 0.8, roughness: 0.4 }));
    under.position.y = 0.0; train.add(under);

    scene.add(train);

    // =====================================================================
    //  HOLOGRAPHIC ORB (wireframe sphere + ring) like reference top
    // =====================================================================
    const holoGroup = new THREE.Group();
    const ico = new THREE.LineSegments(
        new THREE.WireframeGeometry(new THREE.IcosahedronGeometry(3.2, 1)),
        new THREE.LineBasicMaterial({ color: C.cyan, transparent: true, opacity: 0.55 })
    );
    holoGroup.add(ico);
    const holoRing = new THREE.Mesh(new THREE.TorusGeometry(4.6, 0.12, 8, 40), new THREE.MeshBasicMaterial({ color: C.magenta, transparent: true, opacity: 0.9 }));
    holoRing.rotation.x = Math.PI / 2.4; holoGroup.add(holoRing);
    const holoRing2 = new THREE.Mesh(new THREE.TorusGeometry(4.2, 0.06, 8, 40), new THREE.MeshBasicMaterial({ color: C.purple, transparent: true, opacity: 0.8 }));
    holoRing2.rotation.x = Math.PI / 1.8; holoGroup.add(holoRing2);
    const holoGlow = additiveSprite(glowMagenta, 9, 0.35); holoGroup.add(holoGlow);
    holoGroup.position.set(-4, 16, -22);
    scene.add(holoGroup);

    // =====================================================================
    //  CITY : SKYSCRAPERS + HOLO BILLBOARDS + ANTENNAE
    // =====================================================================
    const billboards = [];     // {mat, mesh, phase}
    const blinkers   = [];     // {light, mesh}
    const antennaSpheres = []; // {mat, phase}

    function neonEdges(geo, hex) {
        const e = new THREE.LineSegments(
            new THREE.EdgesGeometry(geo),
            new THREE.LineBasicMaterial({ color: hex, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending })
        );
        return e;
    }

    const windowTexCache = [
        makeWindowTexture(6, 22, "#2af6ff"),
        makeWindowTexture(5, 26, "#ff2bd6"),
        makeWindowTexture(7, 18, "#ffb347"),
        makeWindowTexture(4, 30, "#9b3cff")
    ];

    function makeTower(x, z, h, w, d, neonHex) {
        const group = new THREE.Group();
        const geo = new THREE.BoxGeometry(w, h, d);
        const tex = windowTexCache[(Math.random() * windowTexCache.length) | 0].clone();
        tex.repeat.set(Math.max(1, Math.round(w / 2)), Math.max(1, Math.round(h / 4)));
        tex.needsUpdate = true;
        const mat = new THREE.MeshStandardMaterial({
            map: tex, emissiveMap: tex, emissive: 0xffffff, emissiveIntensity: 1.0,
            color: 0x05070f, metalness: 0.85, roughness: 0.45
        });
        const body = new THREE.Mesh(geo, mat);
        body.position.y = h / 2;
        group.add(body);

        // neon trim edges
        const edges = neonEdges(geo, neonHex);
        edges.position.y = h / 2; group.add(edges);

        // rooftop antennae + blinkers
        const nAnt = 1 + ((Math.random() * 3) | 0);
        for (let a = 0; a < nAnt; a++) {
            const ah = 3 + Math.random() * 6;
            const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.08, ah, 6), new THREE.MeshBasicMaterial({ color: neonHex }));
            ant.position.set((Math.random() - 0.5) * w * 0.6, h + ah / 2, (Math.random() - 0.5) * d * 0.6);
            group.add(ant);
            const blinkHex = Math.random() < 0.5 ? C.magenta : C.cyan;
            const bm = new THREE.MeshBasicMaterial({ color: blinkHex });
            const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 8), bm);
            bulb.position.set(ant.position.x, h + ah, ant.position.z);
            group.add(bulb);
            antennaSpheres.push({ mat: bm, phase: Math.random() * 6.28 });
            const bl = new THREE.PointLight(blinkHex, 0.6, 14, 2);
            bl.position.copy(bulb.position); group.add(bl);
            blinkers.push({ light: bl, mesh: bulb });
        }

        // holographic billboard on a side face
        if (Math.random() < 0.55) {
            const bw = Math.min(w, d) * (0.7 + Math.random() * 0.4);
            const bh = bw * 0.62;
            const btex = makeBillboardTexture(["CYBER", "NEON", "DATA", "SYNTH", "VOID", "FLUX", "9LIFE"][(Math.random() * 7) | 0]);
            const bmat = new THREE.MeshBasicMaterial({ map: btex, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false });
            const bmesh = new THREE.Mesh(new THREE.PlaneGeometry(bw, bh), bmat);
            const side = Math.random() < 0.5 ? 1 : -1;
            const horizontal = Math.random() < 0.5;
            const by = h * (0.45 + Math.random() * 0.45);
            if (horizontal) { bmesh.position.set(0, by, side * (d / 2 + 0.15)); if (side < 0) bmesh.rotation.y = Math.PI; }
            else { bmesh.position.set(side * (w / 2 + 0.15), by, 0); bmesh.rotation.y = side * Math.PI / 2; }
            group.add(bmesh);
            billboards.push({ mat: bmat, phase: Math.random() * 6.28, base: 0.85 });
        }

        group.position.set(x, 0, z);
        group.rotation.y = (Math.random() - 0.5) * 0.5;
        scene.add(group);
        return group;
    }

    // Generate towers flanking the track curve on both sides
    const neonPool = [C.cyan, C.magenta, C.purple, C.amber, C.green, C.pink, C.blue];
    for (let i = 0; i <= 26; i++) {
        const t = i / 26;
        const p = curve.getPointAt(t);
        const tan = curve.getTangentAt(t);
        const nrm = new THREE.Vector3(-tan.z, 0, tan.x).normalize();
        for (let s = -1; s <= 1; s += 2) {
            // skip the immediate corridor (leave room for train)
            const dist = 7 + Math.random() * 22;
            const off = nrm.clone().multiplyScalar(s * dist);
            const x = p.x + off.x + (Math.random() - 0.5) * 4;
            const z = p.z + off.z + (Math.random() - 0.5) * 4;
            const h = 12 + Math.random() * 42;
            const w = 4 + Math.random() * 8;
            const d = 4 + Math.random() * 8;
            makeTower(x, z, h, w, d, neonPool[(Math.random() * neonPool.length) | 0]);
        }
    }

    // Distant background towers (fogged silhouettes with windows)
    for (let i = 0; i < 40; i++) {
        const ang = Math.random() * Math.PI * 2;
        const rad = 60 + Math.random() * 90;
        const x = Math.cos(ang) * rad, z = Math.sin(ang) * rad - 20;
        const h = 20 + Math.random() * 55;
        makeTower(x, z, h, 5 + Math.random() * 9, 5 + Math.random() * 9, neonPool[(Math.random() * neonPool.length) | 0]);
    }

    // =====================================================================
    //  FLOATING NEON PROPS (billboard-like rects & rings in air, like ref)
    // =====================================================================
    const floaters = [];
    for (let i = 0; i < 22; i++) {
        const kind = Math.random();
        if (kind < 0.5) {
            const w = 1.2 + Math.random() * 3.5, h = 0.8 + Math.random() * 2.2;
            const col = neonPool[(Math.random() * neonPool.length) | 0];
            const m = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false });
            const rect = new THREE.Mesh(new THREE.PlaneGeometry(w, h), m);
            rect.position.set((Math.random() - 0.5) * 70, 4 + Math.random() * 22, (Math.random() - 0.5) * 70 - 10);
            rect.rotation.y = Math.random() * Math.PI;
            scene.add(rect);
            floaters.push({ obj: rect, baseY: rect.position.y, phase: Math.random() * 6.28, spin: (Math.random() - 0.5) * 0.6 });
        } else if (kind < 0.8) {
            const r = 0.6 + Math.random() * 1.6;
            const col = neonPool[(Math.random() * neonPool.length) | 0];
            const ring = new THREE.Mesh(new THREE.TorusGeometry(r, 0.07, 6, 24), new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending }));
            ring.position.set((Math.random() - 0.5) * 60, 3 + Math.random() * 18, (Math.random() - 0.5) * 60 - 10);
            ring.rotation.x = Math.random() * Math.PI;
            scene.add(ring);
            floaters.push({ obj: ring, baseY: ring.position.y, phase: Math.random() * 6.28, spin: (Math.random() - 0.5) * 1.2 });
        } else {
            const col = neonPool[(Math.random() * neonPool.length) | 0];
            const lineMat = new THREE.LineBasicMaterial({ color: col, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending });
            const pts = [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 4 + Math.random() * 8, 0)];
            const lg = new THREE.BufferGeometry().setFromPoints(pts);
            const line = new THREE.Line(lg, lineMat);
            line.position.set((Math.random() - 0.5) * 70, 2 + Math.random() * 10, (Math.random() - 0.5) * 70 - 10);
            scene.add(line);
        }
    }

    // =====================================================================
    //  RAIN PARTICLE SYSTEM
    // =====================================================================
    const RAIN_COUNT = 3500;
    const rainGeo = new THREE.BufferGeometry();
    const rainPos = new Float32Array(RAIN_COUNT * 3);
    const rainVel = new Float32Array(RAIN_COUNT);
    const RAIN_AREA = 140, RAIN_TOP = 60;
    for (let i = 0; i < RAIN_COUNT; i++) {
        rainPos[i * 3]     = (Math.random() - 0.5) * RAIN_AREA;
        rainPos[i * 3 + 1] = Math.random() * RAIN_TOP;
        rainPos[i * 3 + 2] = (Math.random() - 0.5) * RAIN_AREA - 10;
        rainVel[i] = 18 + Math.random() * 22;
    }
    rainGeo.setAttribute("position", new THREE.BufferAttribute(rainPos, 3));
    const rainMat = new THREE.PointsMaterial({
        color: 0x9fe8ff, size: 0.12, transparent: true, opacity: 0.55,
        blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
    });
    const rain = new THREE.Points(rainGeo, rainMat);
    scene.add(rain);

    // =====================================================================
    //  SPLASH RINGS POOL
    // =====================================================================
    const splashPool = [];
    const SPLASH_MAX = 36;
    for (let i = 0; i < SPLASH_MAX; i++) {
        const geo = new THREE.RingGeometry(0.05, 0.12, 16);
        const mat = new THREE.MeshBasicMaterial({ color: C.cyan, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false });
        const ring = new THREE.Mesh(geo, mat);
        ring.rotation.x = -Math.PI / 2;
        ring.visible = false;
        scene.add(ring);
        splashPool.push({ mesh: ring, mat: mat, life: 0 });
    }
    let splashIdx = 0;
    function spawnSplash(x, z) {
        const s = splashPool[splashIdx]; splashIdx = (splashIdx + 1) % SPLASH_MAX;
        s.mesh.position.set(x, 0.04, z);
        s.mesh.scale.set(0.3, 0.3, 0.3);
        s.mat.opacity = 0.7; s.life = 1.0; s.mesh.visible = true;
        s.mat.color.setHex(Math.random() < 0.5 ? C.cyan : C.magenta);
    }

    // =====================================================================
    //  POST-PROCESSING : BLOOM  (with graceful fallback)
    // =====================================================================
    let composer = null;
    try {
        composer = new THREE.EffectComposer(renderer);
        composer.addPass(new THREE.RenderPass(scene, camera));
        const bloom = new THREE.UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.95, 0.65, 0.22);
        composer.addPass(bloom);
    } catch (e) {
        composer = null;
    }

    // =====================================================================
    //  SCREEN STREAKS (DOM overlay)
    // =====================================================================
    const streaksEl = document.getElementById("streaks");
    for (let i = 0; i < 14; i++) {
        const sp = document.createElement("span");
        sp.style.left = (Math.random() * 100) + "%";
        sp.style.animationDelay = (Math.random() * 1.4) + "s";
        sp.style.animationDuration = (1.0 + Math.random() * 1.2) + "s";
        sp.style.opacity = (0.3 + Math.random() * 0.6);
        streaksEl.appendChild(sp);
    }

    // =====================================================================
    //  INTERACTION : camera modes
    // =====================================================================
    let cinematic = false;
    const modeEl = document.getElementById("mode");
    const homePos = camera.position.clone();
    const homeTarget = controls.target.clone();

    window.addEventListener("keydown", (e) => {
        const k = e.key.toLowerCase();
        if (k === "c") {
            cinematic = !cinematic;
            controls.autoRotate = !cinematic;
            modeEl.textContent = "MODE: " + (cinematic ? "CINEMATIC" : "ORBIT");
        } else if (k === "r") {
            cinematic = false; controls.autoRotate = true; modeEl.textContent = "MODE: ORBIT";
            camera.position.copy(homePos); controls.target.copy(homeTarget); controls.update();
        }
    });

    // =====================================================================
    //  ANIMATION LOOP
    // =====================================================================
    const clock = new THREE.Clock();
    let trainT = 0.02;
    const trainSpeed = 0.018; // fraction of curve per second
    const statsEl = document.getElementById("stats");
    let frames = 0, fpsAccum = 0, lastFps = 0;
    const tmpV = new THREE.Vector3();

    function animate() {
        const dt = Math.min(clock.getDelta(), 0.05);
        const time = clock.elapsedTime;

        // --- Train along curve ---
        trainT += trainSpeed * dt;
        if (trainT > 0.999) trainT = 0.02;
        const pos = curve.getPointAt(trainT);
        const tan = curve.getTangentAt(trainT);
        train.position.copy(pos);
        tmpV.copy(pos).add(tan);
        train.lookAt(tmpV);
        // gentle bob
        train.position.y += Math.sin(time * 2.0) * 0.05;

        // thruster pulse
        const pulse = 0.8 + Math.sin(time * 9) * 0.25;
        thrusterLights.forEach(tl => { tl.light.intensity = 1.0 * pulse; tl.glow.material.opacity = 0.7 * pulse; });

        // headlight flicker
        head.intensity = 2.0 + Math.sin(time * 17) * 0.3;

        // track lights drift along
        for (let i = 0; i < trackLights.length; i++) {
            const lt = (trainT + i / trackLights.length) % 1;
            const lp = curve.getPointAt(lt);
            trackLights[i].position.set(lp.x, lp.y - 1.0, lp.z);
            trackLights[i].intensity = 1.2 + Math.sin(time * 3 + i) * 0.4;
        }

        // holo orb spin
        holoGroup.rotation.y += dt * 0.4;
        ico.rotation.x += dt * 0.25; ico.rotation.z += dt * 0.18;
        holoRing.rotation.z += dt * 0.6; holoRing2.rotation.z -= dt * 0.45;
        holoGroup.position.y = 16 + Math.sin(time * 0.6) * 0.6;

        // billboards flicker
        for (let i = 0; i < billboards.length; i++) {
            const b = billboards[i];
            let o = b.base + Math.sin(time * 6 + b.phase) * 0.12;
            if (Math.random() < 0.02) o *= 0.2; // glitch
            b.mat.opacity = Math.max(0.1, Math.min(1, o));
        }

        // antenna blinkers
        for (let i = 0; i < antennaSpheres.length; i++) {
            const a = antennaSpheres[i];
            const on = (Math.sin(time * 4 + a.phase) > 0.2);
            a.mat.opacity = on ? 1 : 0.12;
            a.mat.transparent = true;
        }
        for (let i = 0; i < blinkers.length; i++) {
            blinkers[i].light.intensity = (Math.sin(time * 4 + i * 0.7) > 0.2) ? 0.7 : 0.05;
        }

        // floaters bob & spin
        for (let i = 0; i < floaters.length; i++) {
            const f = floaters[i];
            f.obj.position.y = f.baseY + Math.sin(time * 0.8 + f.phase) * 0.8;
            f.obj.rotation.y += dt * f.spin;
        }

        // --- Rain update ---
        const arr = rainGeo.attributes.position.array;
        for (let i = 0; i < RAIN_COUNT; i++) {
            arr[i * 3 + 1] -= rainVel[i] * dt;
            // slight slant
            arr[i * 3] += dt * 2.0;
            if (arr[i * 3 + 1] <= 0) {
                // occasionally spawn splash where it lands
                if (Math.random() < 0.06) spawnSplash(arr[i * 3], arr[i * 3 + 2]);
                arr[i * 3]     = (Math.random() - 0.5) * RAIN_AREA;
                arr[i * 3 + 1] = RAIN_TOP + Math.random() * 8;
                arr[i * 3 + 2] = (Math.random() - 0.5) * RAIN_AREA - 10;
            }
        }
        rainGeo.attributes.position.needsUpdate = true;

        // random ambient splashes near track
        if (Math.random() < 0.25) {
            const sp = curve.getPointAt(Math.random());
            spawnSplash(sp.x + (Math.random() - 0.5) * 8, sp.z + (Math.random() - 0.5) * 8);
        }

        // --- Splash rings update ---
        for (let i = 0; i < SPLASH_MAX; i++) {
            const s = splashPool[i];
            if (s.life > 0) {
                s.life -= dt * 1.6;
                const sc = 0.3 + (1 - s.life) * 2.2;
                s.mesh.scale.set(sc, sc, sc);
                s.mat.opacity = Math.max(0, s.life * 0.7);
                if (s.life <= 0) s.mesh.visible = false;
            }
        }

        // --- Camera ---
        if (cinematic) {
            // dolly behind the train, looking forward down the track
            const camT = (trainT - 0.035 + 1) % 1;
            const cp = curve.getPointAt(camT);
            const ct = curve.getTangentAt(camT);
            const desired = cp.clone().add(new THREE.Vector3(0, 2.4, 0)).add(ct.clone().multiplyScalar(-5.5));
            camera.position.lerp(desired, 0.04);
            const look = train.position.clone().add(new THREE.Vector3(0, 1.2, 0));
            controls.target.lerp(look, 0.06);
        }
        controls.update();

        // --- Render ---
        if (composer) composer.render();
        else renderer.render(scene, camera);

        // fps readout
        frames++; fpsAccum += dt;
        if (fpsAccum >= 0.5) { lastFps = Math.round(frames / fpsAccum); frames = 0; fpsAccum = 0;
            statsEl.textContent = "RAIL STATUS ONLINE // WEATHER:RAIN // FPS " + lastFps; }
    }

    animate();

    // =====================================================================
    //  RESIZE
    // =====================================================================
    window.addEventListener("resize", () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
        if (composer) composer.setSize(window.innerWidth, window.innerHeight);
    });

})();
</script>
</body>
